-- lazy.nvim and every plugin come from the Nix store;
-- `require("nix")` is generated by modules/editor/neovim.nix.
local nix = require("nix")

vim.g.mapleader = " "
vim.g.maplocalleader = "\\"

require("config.options")
require("config.keymaps")
require("config.autocmds")

vim.opt.rtp:prepend(nix.lazy)

require("lazy").setup({
  spec = { { import = "plugins" } },
  -- Every plugin is looked up in the Nix-built directory first and only
  -- downloaded if it isn't there.
  dev = { path = nix.plugins, patterns = { "" }, fallback = true },
  -- The config directory is read-only
  lockfile = vim.fn.stdpath("state") .. "/lazy-lock.json",
  install = { missing = true, colorscheme = { "habamax" } },
  checker = { enabled = false },
  change_detection = { enabled = false },
  rocks = { enabled = false },
  ui = { border = "rounded" },
  performance = {
    rtp = {
      disabled_plugins = { "gzip", "tarPlugin", "tohtml", "tutor", "zipPlugin" },
    },
  },
})

require("config.colors").apply()
